       XCTAssertEqual(
-        CLIVCSWriter.opDirectory(.abortRebase, path: "/w/room", vcs: vcs, projectRoot: "/p"),
-        "/w/room")
+        CLIVCSWriter.opDirectory(action, path: "/w/room", projectRoot: "/p"), "/w/room",
